#include <bits/stdc++.h>
using namespace std;
const int MAXN = 15000;
struct Edge {
    int to, capacity, flow, cost;
};
vector<Edge> edges;
vector<int> adj[MAXN];
long long total_cost, dist[MAXN];
int n, m, k, c, d, p[MAXN], pe[MAXN], in_queue[MAXN], source=9998, sink=9999, current, i, j;
void addEdge(int x, int y, int cap, int cost) {
    adj[x].push_back(edges.size()); edges.push_back({y, cap, 0, cost});
    adj[y].push_back(edges.size()); edges.push_back({x, 0, 0, -cost});
}
void sendRebels() {
    fill(dist, dist + 10000, (long long)1e18);
    fill(p, p + 10000, -1);
    fill(pe, pe + 10000, -1);
    fill(in_queue, in_queue + 10000, 0);
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    in_queue[source] = 1;
    current = sink;
    while (!q.empty()) {
        int k = q.front(); q.pop();
        in_queue[k] = 0;
        for (auto edge_idx : adj[k]) {
            if (edges[edge_idx].capacity - edges[edge_idx].flow == 0) continue;
            int cost = edges[edge_idx].cost, y = edges[edge_idx].to;
            if (dist[y] > dist[k] + cost) {
                dist[y] = dist[k] + cost;
                p[y] = k;
                pe[y] = edge_idx;
                if (!in_queue[y]) { in_queue[y] = 1; q.push(y); }
            }
        }
    }
    int cur_node = current;
    while (cur_node != source) {
        edges[pe[cur_node]].flow++;
        edges[pe[cur_node] ^ 1].flow--;
        cur_node = p[cur_node];
    }
    total_cost += dist[sink];
}
int main() {
    cin >> n >> m >> k >> c >> d;
    int x, y;
    for (int i = 1; i <= k; i++) { cin >> x; x--; addEdge(source, x, 1, 0); }
    for (int i = 1; i <= 101; i++) addEdge((i - 1) * n, sink, k, (i - 1) * c);
    for (int i = 1; i <= m; i++) {
        cin >> x >> y; x--; y--;
        for (int i = 1; i <= 100; i++) {
            for (int j = 1; j <= k; j++) {
                addEdge(x + (i - 1) * n, y + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                addEdge(y + (i - 1) * n, x + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= 100; j++) {
            addEdge(i - 1 + (j - 1) * n, i - 1 + (j - 1) * n + n, k, 0);
        }
    }
    for (int i = 1; i <= k; i++) sendRebels();
    cout << total_cost << endl;
    return 0;
}
